from scipy import ndimage
def comps(mask):
    lab,n=ndimage.label(mask, structure=np.ones((3,3)))
    res=[]
    for i in range(1,n+1):
        m=lab==i
        ys,xs=np.where(m)
        # normalized shape
        sub=m[ys.min():ys.max()+1, xs.min():xs.max()+1].astype(int)
        res.append((m.sum(),(ys.min(),ys.max(),xs.min(),xs.max()),[''.join(map(str,row)) for row in sub]))
    return res
